module tb;

  // ------------------------------------------------------------
  // Parameters and DUT signal declarations
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8;               // 125 MHz clock
  // DUT ports
  logic        clk;
  logic        rst;
  logic [15:0] prescale;
  logic        rxd;
  // AXI‑stream slave side (tied‑off)
  logic [7:0]  s_axis_tdata;
  logic        s_axis_tvalid;
  logic        s_axis_tready;
  // AXI‑stream master side (observed by the testbench)
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;
  // Unused status outputs
  logic        tx_busy;
  logic        rx_busy;
  logic        rx_overrun_error;
  logic        rx_frame_error;
  logic        txd;  // not used externally

  // ------------------------------------------------------------
  // Clock generation
  // ------------------------------------------------------------
  initial clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  // Reset stimulus
  // ------------------------------------------------------------
  initial begin
    rst = 1'b1;
    # (CLK_PERIOD*2);
    rst = 1'b0;
    # (CLK_PERIOD*2);
  end

  // ------------------------------------------------------------
  // Tie‑off the AXI‑stream slave interface
  // ------------------------------------------------------------
  assign s_axis_tdata  = 8'h00;
  assign s_axis_tvalid = 1'b0;
  assign s_axis_tready = 1'b1;  // always ready

  // ------------------------------------------------------------
  // Instantiate the DUT (uart) – top‑level module must be named tb
  // ------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .txd          (),
    .tx_busy      (),
    .rx_busy      (),
    .rx_overrun_error(),
    .rx_frame_error(),
    .prescale     (prescale)
  );

  // ------------------------------------------------------------
  // Helper timing tasks
  // ------------------------------------------------------------
  task automatic wait_clks (input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic send_byte (input bit [7:0] data);
    int bit_clks;
    bit_clks = int'(prescale) * 8;
    // start bit
    @(negedge clk);
    rxd = 1'b0;
    wait_clks(bit_clks);
    // data bits – LSB first
    for (int i = 0; i < 8; i++) begin
      @(negedge clk);
      rxd = data[i];
      wait_clks(bit_clks);
    end
    // stop bit
    @(negedge clk);
    rxd = 1'b1;
    wait_clks(bit_clks);
  endtask

  // ------------------------------------------------------------
  // Main stimulus: two consecutive words 0x12, 0x34 with prescale
  // changed to 2 for the second word.
  // ------------------------------------------------------------
  initial begin
    // Default prescale used for the first frame
    prescale = 16'd5;

    // ---- Send first word 0x12 ----
    send_byte(8'h12);
    // Wait until the receiver becomes idle again (busy low)
    wait (!dut.uart_rx_inst.busy);
    // ---- Change prescale to 2 for the second frame ----
    prescale = 16'd2;
    // ---- Send second word 0x34 ----
    send_byte(8'h34);

    // --------------------------------------------------------
    // Wait for the coverage point R22_rx_prescale2_two_words to be hit.
    // The coverage property watches m_axis_tvalid and m_axis_tdata.
    // --------------------------------------------------------
    int cnt = 0;
    while (cnt < 500) begin
      if (dut.uart_rx_inst.m_axis_tvalid &&
          dut.uart_rx_inst.m_axis_tdata == 8'h34) begin
        $finish;                              // clean end of simulation
      end
      @(negedge clk);
      cnt++;
    end
    // If we exit the loop the coverage was not observed – fail
    $fatal(1, "Coverage point R22_rx_prescale2_two_words not hit");
  end

endmodule

module tb;
  // -------------------------------------------------
  // Parameters and signal declarations
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8;               // 125 MHz
  localparam logic [15:0] PRESCALE = 16'd5;    // same as baseline
  // Clock
  logic clk;
  // Reset and control
  logic rst;
  logic [15:0] prescale;
  // UART RX interface signals
  logic rxd;                     // input to uart_rx
  logic m_axis_tready;           // input to uart_rx
  // DUT outputs
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       busy;
  logic       overrun_error;
  logic       frame_error;       // covered by cov_R23
  // -------------------------------------------------
  // Clock generation
  // -------------------------------------------------
  initial clk = 1'b0;
  always #(CLK_PERIOD/2) clk = ~clk;
  // -------------------------------------------------
  // Reset task
  // -------------------------------------------------
  task automatic do_reset();
    rst = 1'b0;
    #(CLK_PERIOD*2);
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
    #(CLK_PERIOD*2);
  endtask
  // -------------------------------------------------
  // Helper: wait for N negedge clock events
  // -------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask
  // -------------------------------------------------
  // Helper: bit period length in clocks
  // -------------------------------------------------
  function int bit_clks();
    return int'(PRESCALE) * 8;
  endfunction
  // -------------------------------------------------
  // Task: generate a frame that ends with a low stop bit (frame error)
  // -------------------------------------------------
  task automatic cause_frame_error();
    // start bit
    rxd = 1'b0;
    wait_clks(bit_clks());
    // 8 data bits (arbitrary, all 0)
    for (int i=0; i<8; i++) begin
      rxd = 1'b0;
      wait_clks(bit_clks());
    end
    // stop bit low – causes frame_error
    rxd = 1'b0;
    wait_clks(bit_clks());
    // return to idle (high)
    rxd = 1'b1;
    wait_clks(bit_clks());
  endtask
  // -------------------------------------------------
  // Task: transmit a normal frame with a given data byte
  // -------------------------------------------------
  task automatic send_good_byte(input byte unsigned data_byte);
    // start bit
    rxd = 1'b0;
    wait_clks(bit_clks());
    // data bits, LSB first
    for (int i=0; i<8; i++) begin
      rxd = data_byte[i];
      wait_clks(bit_clks());
    end
    // stop bit high
    rxd = 1'b1;
    wait_clks(bit_clks());
  endtask
  // -------------------------------------------------
  // Main simulation
  // -------------------------------------------------
  initial begin
    // Initialise signals
    prescale = PRESCALE;
    rst      = 1'b0;
    rxd      = 1'b1;
    m_axis_tready = 1'b1;

    // Reset the design
    do_reset();

    // Allow a few cycles for the DUT to come out of reset
    repeat (10) @(posedge clk);

    // ----------------------------------------------------------------
    // 1) Force a frame error by sending a frame with a low stop bit
    // ----------------------------------------------------------------
    cause_frame_error();

    // ----------------------------------------------------------------
    // 2) Wait until the receiver is idle (busy = 0 and rxd = 1) for
    //    at least 16 consecutive clock cycles.
    // ----------------------------------------------------------------
    int idle_cnt = 0;
    while (idle_cnt < 16) begin
      @(posedge clk);
      if (!busy && rxd) begin
        idle_cnt = idle_cnt + 1;
      end else begin
        idle_cnt = 0; // restart counter if condition is broken
      end
    end

    // Ensure that no frame_error is still asserted before proceeding
    while (frame_error) begin
      @(posedge clk);
    end

    // ----------------------------------------------------------------
    // 3) Transmit the recovery byte 0xA5
    // ----------------------------------------------------------------
    send_good_byte(8'hA5);

    // Wait for the rise of m_axis_tvalid – this is the moment the covered
    // property becomes true.
    @(posedge clk) wait until (m_axis_tvalid);

    // Optional small margin
    repeat (5) @(posedge clk);

    // End of test
    $display("TESTBENCH COMPLETED");
    $finish;
  end
endmodule

module tb;

  // -------------------------------------------------
  // Clock generation
  // -------------------------------------------------
  localparam int CLK_PERIOD = 10; // 100 MHz
  reg clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // -------------------------------------------------
  // DUT ports
  // -------------------------------------------------
  reg rst = 0;
  reg [7:0] s_axis_tdata;
  reg s_axis_tvalid;
  wire s_axis_tready;
  wire txd;
  wire busy;

  // -------------------------------------------------
  // DUT instantiation (uart_tx, prescale = 1)
  // -------------------------------------------------
  uart_tx #(.DATA_WIDTH(8)) dut (
    .clk            (clk),
    .rst            (rst),
    .s_axis_tdata   (s_axis_tdata),
    .s_axis_tvalid  (s_axis_tvalid),
    .s_axis_tready  (s_axis_tready),
    .txd            (txd),
    .busy           (busy),
    .prescale       (16'd1)   // prescale = 16'd1 as required by coverage point
  );

  // -------------------------------------------------
  // Reset sequencing
  // -------------------------------------------------
  initial begin
    rst = 1;
    #(CLK_PERIOD*2);
    rst = 0;
    #(CLK_PERIOD*2);
  end

  // -------------------------------------------------
  // Stimulus
  // -------------------------------------------------
  initial begin
    // Wait until the DUT is idle (busy = 0 and s_axis_tready = 1)
    wait (busy == 0 && s_axis_tready == 1);

    // ---- First word -------------------------------------------------
    s_axis_tdata  = 8'h5A;        // first payload byte
    s_axis_tvalid = 1'b1;
    @(posedge clk);
    // Keep tvalid high for the next cycle to request a second word
    s_axis_tvalid = 1'b1;
    @(posedge clk);
    // Load second payload byte while tvalid is still high
    s_axis_tdata  = 8'hA5;
    @(posedge clk);
    // End of back‑to‑back request – drop tvalid so that it will be low
    // on the cycle when the coverage point fires
    s_axis_tvalid = 1'b0;

    // -------------------------------------------------
    // Wait for the coverage point to be hit:
    //   $fell(busy)           – busy goes low
    //   $rose(s_axis_tready) – ready goes high
    //   !$past(s_axis_tvalid) – s_axis_tvalid was low on the previous cycle
    // When all three conditions are true the target cover property fires.
    // -------------------------------------------------
    wait ($fell(busy) && $rose(s_axis_tready) && !$past(s_axis_tvalid));
    $finish;
  end

endmodule

