module tb;

  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd1;

  logic        clk = 1'b0;
  logic        rst = 1'b1;
  logic        rxd = 1'b1;
  logic [7:0]  s_axis_tdata = '0;
  logic        s_axis_tvalid = 1'b0;
  logic        m_axis_tready = 1'b1;
  logic [15:0] prescale = PRESCALE;
  wire  [7:0]  m_axis_tdata;
  wire         m_axis_tvalid;
  wire         s_axis_tready;
  wire         txd;
  wire         tx_busy, rx_busy;
  wire         rx_overrun_error, rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart #(.DATA_WIDTH(8)) dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1;
    wait_clks(4);
    rst = 1'b0;
    wait_clks(4);
  endtask

  task automatic uart_send_byte(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    rxd = 1'b0;
    wait_clks(bit_clks);
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_clks(bit_clks);
    end
    rxd = 1'b1;
    wait_clks(bit_clks);
  endtask

  // Drive a frame and assert rst at the stop-bit sample posedge.
  // With prescale=1: stop sample is at posedge 77 from start of frame.
  // In negedge terms: rxd=1 at negedge 75, rst=1 at negedge 76.
  task automatic interrupt_at_stop();
    rxd = 1'b0;
    wait_clks(75);
    rxd = 1'b1;
    wait_clks(1);
    rst = 1'b1;
    wait_clks(4);
    rst = 1'b0;
    wait_clks(4);
  endtask

  initial begin
    do_reset();
    wait_clks(20);

    interrupt_at_stop();

    wait_clks(20);

    uart_send_byte(8'h5A);

    wait (m_axis_tvalid);
    wait_clks(1);

    if (m_axis_tdata !== 8'h5A)
      $fatal(1, "FAIL: expected 0x5A, got 0x%02h", m_axis_tdata);

    $display("PASS R27: m_axis_tdata = 0x%02h", m_axis_tdata);
    $finish;
  end

  initial begin
    #100000;
    $fatal(1, "timeout");
  end

endmodule

