module tb;
  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;

  logic        clk = 1'b0;
  logic        rst = 1'b0;
  logic [7:0]  s_axis_tdata = '0;
  logic        s_axis_tvalid = 1'b0;
  logic [15:0] prescale = PRESCALE;
  wire         s_axis_tready;
  wire         txd;
  wire         tx_busy;
  wire         rx_busy;
  wire         rx_overrun_error;
  wire         rx_frame_error;
  wire [7:0]   m_axis_tdata;
  wire         m_axis_tvalid;
  logic        m_axis_tready = 1'b1;
  logic        rxd = 1'b1;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  // Read internal bit_cnt for synchronization (allowed: reading only)
  wire [3:0] tx_bit_cnt = dut.uart_tx_inst.bit_cnt;

  initial begin
    // --- Reset ---
    rst = 1'b1;
    s_axis_tvalid = 1'b0;
    s_axis_tdata  = '0;
    repeat (4) @(negedge clk);
    rst = 1'b0;
    repeat (2) @(negedge clk);

    // --- Wait for TX to be ready (idle) ---
    wait (s_axis_tready === 1'b1);
    @(negedge clk);

    // --- Step 1: Start frame A with 8'hA5 ---
    s_axis_tdata  = 8'hA5;
    s_axis_tvalid = 1'b1;
    @(posedge clk);    // Handshake: DUT loads 8'hA5, becomes busy, tready drops
    @(negedge clk);    // Drop tvalid — legal: previous edge had tready=1
    s_axis_tvalid = 1'b0;

    // --- Step 2: Wait until bit_cnt == 4 (mid data-bits of frame A) ---
    do begin
      @(negedge clk);
    end while (tx_bit_cnt !== 4'd4);

    // --- Step 3: Assert tvalid with 8'h3C (mid-frame rise) ---
    s_axis_tdata  = 8'h3C;
    s_axis_tvalid = 1'b1;

    // --- Step 4: Hold tvalid/tdata stable until frame A ends and frame B loads ---
    // Wait for bit_cnt to reach 0 (stop-bit period of frame A)
    do begin
      @(negedge clk);
    end while (tx_bit_cnt !== 4'd0);

    // Wait for bit_cnt to return to 9 (DUT has loaded 8'h3C as frame B)
    do begin
      @(negedge clk);
    end while (tx_bit_cnt !== 4'd9);

    // --- Step 5: Frame B loaded. Drop tvalid (legal: handshake just occurred) ---
    s_axis_tvalid = 1'b0;

    // --- Step 6: Wait for frame B to complete ---
    do begin
      @(negedge clk);
    end while (tx_busy !== 1'b0);

    // Allow a few extra clocks for coverage sampling to settle
    repeat (20) @(negedge clk);

    $display("PASS: T11 coverage should be hit");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end

endmodule

