module tb;
  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd2;

  logic        clk = 1'b0;
  logic        rst = 1'b0;
  logic [7:0]  s_axis_tdata = 8'h00;
  logic        s_axis_tvalid = 1'b0;
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready = 1'b1;
  logic        rxd = 1'b1;
  logic [15:0] prescale = PRESCALE;
  wire         s_axis_tready;
  wire         txd;
  wire         tx_busy;
  wire         rx_busy;
  wire         rx_overrun_error;
  wire         rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  wire [3:0]  bit_cnt = dut.uart_tx_inst.bit_cnt;
  wire [18:0] prescale_reg = dut.uart_tx_inst.prescale_reg;

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    begin
      rst = 1'b1;
      wait_clks(4);
      rst = 1'b0;
      wait_clks(2);
    end
  endtask

  initial begin
    s_axis_tdata  = 8'h00;
    s_axis_tvalid = 1'b0;
    prescale      = PRESCALE;
    rxd           = 1'b1;
    m_axis_tready = 1'b1;

    do_reset();
    wait_clks(2);

    // Phase 1: Load 8'hA5, hold tvalid through frame 1
    @(negedge clk);
    s_axis_tdata  = 8'hA5;
    s_axis_tvalid = 1'b1;
    @(negedge clk);
    @(negedge clk);
    wait(s_axis_tready);
    @(negedge clk);
    s_axis_tvalid = 1'b0;

    // Phase 2: Wait for frame 2 to reach bit_cnt==5
    wait(tx_busy && bit_cnt == 4'd5);
    @(negedge clk);

    // Phase 3: Assert tvalid mid-frame with 8'h3C
    s_axis_tdata  = 8'h3C;
    s_axis_tvalid = 1'b1;

    // Phase 4: Hold tvalid until frame 2 completes
    wait(s_axis_tready);
    @(negedge clk);
    s_axis_tvalid = 1'b0;

    // Phase 5: Wait for 8'h3C frame to be sent
    wait_clks(250);

    $display("T11 test complete");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end

endmodule

module tb;
  localparam int CLK_PERIOD = 8;

  logic clk = 1'b0;
  logic rst = 1'b1;
  logic [7:0] s_axis_tdata = '0;
  logic s_axis_tvalid = 1'b0;
  logic [15:0] prescale = 16'd1;
  wire s_axis_tready;
  wire txd;
  wire tx_busy;
  wire [7:0] m_axis_tdata;
  wire m_axis_tvalid;
  logic m_axis_tready = 1'b1;
  logic rxd = 1'b1;
  wire rx_busy;
  wire rx_overrun_error;
  wire rx_frame_error;

  always #(CLK_PERIOD/2) clk = ~clk;

  uart dut (
    .clk(clk), .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  initial begin
    // Reset
    rst = 1'b1;
    wait_clks(4);
    rst = 1'b0;
    wait_clks(2);

    // Send word 1
    s_axis_tdata = 8'hA5;
    s_axis_tvalid = 1'b1;

    // Wait for word 1 to be accepted
    // tready should be 1 after 1 clock (DUT idle)
    wait_clks(1);

    // Send word 2 (back-to-back)
    s_axis_tdata = 8'h3C;
    // tvalid stays 1

    // Wait for word 2 to be accepted
    // This takes ~80 clocks (word 1 transmission)
    // Wait for tready to go high (word 2 accepted)
    // Actually, for back-to-back, tready never goes high between words
    // So we need to wait for the full transmission of word 2

    // Wait for both words to complete
    // Word 1: ~80 clocks, Word 2: ~80 clocks
    // Total: ~160 clocks
    wait_clks(200);

    // Drop tvalid
    s_axis_tvalid = 1'b0;
    wait_clks(10);

    $display("PASS tb: T12 scenario completed");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end
endmodule
